import subprocess

from meeting_summarizer import audio


def _make_tone(path, seconds):
    # Synthetic 440 Hz tone generated by ffmpeg itself: no fixture file needed.
    subprocess.run(
        [audio.ffmpeg_exe(), "-loglevel", "error", "-y", "-f", "lavfi",
         "-i", f"sine=frequency=440:duration={seconds}", str(path)],
        check=True,
    )


def test_extract_splits_into_parts(tmp_path):
    src = tmp_path / "tone.wav"
    _make_tone(src, 5)
    parts = audio.extract_audio_parts(src, tmp_path / "out", segment_seconds=2)
    assert [p.name for p in parts] == ["part_000.mp3", "part_001.mp3", "part_002.mp3"]


def test_compress_audio_is_small(tmp_path):
    src = tmp_path / "tone.wav"
    _make_tone(src, 5)
    out = audio.compress_audio(src, tmp_path / "small.mp3")
    assert out.stat().st_size < src.stat().st_size / 5
